import { createHash } from "node:crypto";
import { readdirSync, readFileSync, existsSync } from "node:fs";
import { posix, resolve } from "node:path";
import * as ts from "typescript/unstable/ast";
import { API } from "typescript/unstable/sync";
import { createVirtualFileSystem } from "typescript/unstable/fs";
import { catalogs } from "../../src/shared/i18n/index.js";

export type OutboundSurface = {
  id: string;
  file: string;
  locator: string;
  kind: "message" | "edit" | "button" | "alert" | "projection";
  expression: string;
  digest: string;
  dependencies: string;
  keys: string[];
  evidence?: { file: string; case: string; locales: readonly ["en", "uk"] };
  dynamic?: { position: string; reason: string };
  residual?: string;
};

export function productionSources(directory = "src"): Record<string, string> {
  const result: Record<string, string> = {};
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const path = `${directory}/${entry.name}`;
    // Generated ORM source is not application output; it is never a Telegram producer.
    if (entry.isDirectory() && entry.name !== "generated")
      Object.assign(result, productionSources(path));
    else if (entry.isFile() && path.endsWith(".ts"))
      result[path] = readFileSync(path, "utf8");
  }
  return result;
}

const hash = (text: string) =>
  createHash("sha256").update(text).digest("hex").slice(0, 20);
function walk(node: ts.Node, visit: (node: ts.Node) => void) {
  visit(node);
  node.forEachChild((child) => walk(child, visit));
}
function owner(node: ts.Node): string {
  for (
    let parent: ts.Node | undefined = node.parent;
    parent;
    parent = parent.parent
  ) {
    if (ts.isFunctionDeclaration(parent) && parent.name)
      return parent.name.text;
    if (ts.isVariableDeclaration(parent) && ts.isIdentifier(parent.name))
      return parent.name.text;
    if (ts.isMethodDeclaration(parent)) return parent.name.getText();
  }
  return "module";
}

/** Parse real AST nodes, including local/import references. No source-text regex sink discovery. */
export function discoverSurfaces(
  sources: Record<string, string>,
): OutboundSurface[] {
  // TypeScript 7 exposes parsing through its native API, not the removed TS6 createSourceFile API.
  const root = resolve(".outbound-inventory-virtual").replaceAll("\\", "/");
  const config = `${root}/tsconfig.json`;
  const api = new API({
    fs: createVirtualFileSystem({
      [config]: JSON.stringify({
        files: Object.keys(sources),
        compilerOptions: { noLib: true, noResolve: true },
      }),
      ...Object.fromEntries(
        Object.entries(sources).map(([file, source]) => [
          `${root}/${file}`,
          source,
        ]),
      ),
    }),
  });
  const files = new Map<string, ts.SourceFile>();
  try {
    const snapshot = api.updateSnapshot({ openProjects: [config] });
    const project = snapshot.getProjects()[0];
    if (!project) throw new Error("inventory AST project unavailable");
    for (const file of Object.keys(sources)) {
      const ast = project.program.getSourceFile(`${root}/${file}`);
      if (!ast) throw new Error(`inventory AST unavailable: ${file}`);
      files.set(file, ast);
    }
    snapshot.dispose();
  } finally {
    api.close();
  }
  const declarations = new Map<string, ts.Node>();
  const aliases = new Map<string, string>();
  for (const [file, ast] of files)
    walk(ast, (node) => {
      if (
        (ts.isFunctionDeclaration(node) || ts.isVariableDeclaration(node)) &&
        node.name &&
        ts.isIdentifier(node.name)
      )
        declarations.set(`${file}:${node.name.text}`, node);
      if (
        ts.isImportDeclaration(node) &&
        ts.isStringLiteral(node.moduleSpecifier) &&
        node.moduleSpecifier.text.startsWith(".")
      ) {
        const target = posix
          .normalize(posix.join(posix.dirname(file), node.moduleSpecifier.text))
          .replace(/\.js$/, ".ts");
        const bindings = node.importClause?.namedBindings;
        if (bindings && ts.isNamedImports(bindings))
          for (const binding of bindings.elements)
            aliases.set(
              `${file}:${binding.name.text}`,
              `${target}:${binding.propertyName?.text ?? binding.name.text}`,
            );
      }
    });
  const keysFor = (
    node: ts.Node,
    file: string,
    seen = new Set<string>(),
    dependencies = new Map<string, string>(),
  ): Set<string> => {
    const result = new Set<string>();
    walk(node, (child) => {
      if (
        (ts.isStringLiteral(child) ||
          ts.isNoSubstitutionTemplateLiteral(child)) &&
        Object.hasOwn(catalogs.en, child.text)
      )
        result.add(child.text);
      if (ts.isTemplateExpression(child)) {
        for (const key of Object.keys(catalogs.en))
          if (child.head.text.includes(".") && key.startsWith(child.head.text))
            result.add(key);
      }
      if (ts.isIdentifier(child)) {
        const ref =
          aliases.get(`${file}:${child.text}`) ?? `${file}:${child.text}`;
        if (seen.has(ref) || ref.includes("/shared/i18n/")) return;
        seen.add(ref);
        const declaration = declarations.get(ref);
        if (declaration) {
          dependencies.set(ref, declaration.getText().replaceAll("\r\n", "\n"));
          for (const key of keysFor(
            declaration,
            ref.slice(0, ref.lastIndexOf(":")),
            seen,
            dependencies,
          ))
            result.add(key);
        }
      }
    });
    return result;
  };
  const result: OutboundSurface[] = [];
  for (const [file, ast] of files) {
    const counters = new Map<string, number>();
    const add = (node: ts.Node, kind: OutboundSurface["kind"], tag: string) => {
      const base = `${owner(node)}:${tag}`;
      const count = (counters.get(base) ?? 0) + 1;
      counters.set(base, count);
      const expression = node.getText(ast).replaceAll("\r\n", "\n");
      const enclosing = declarations.get(`${file}:${owner(node)}`) ?? node;
      const dependencies = new Map<string, string>();
      const keys = [
        ...keysFor(enclosing, file, new Set(), dependencies),
      ].sort();
      result.push({
        id: `${file}#${base}:${count}`,
        file,
        locator: `${base}:${count}`,
        kind,
        expression,
        digest: hash(expression),
        dependencies: hash(JSON.stringify([...dependencies].sort())),
        keys,
      });
    };
    walk(ast, (node) => {
      if (
        ts.isCallExpression(node) &&
        ts.isPropertyAccessExpression(node.expression)
      ) {
        const name = node.expression.name.text;
        if (
          [
            "sendMessage",
            "reply",
            "editMessageText",
            "answerCallbackQuery",
          ].includes(name)
        )
          add(
            node,
            name === "answerCallbackQuery"
              ? "alert"
              : name === "editMessageText"
                ? "edit"
                : "message",
            name,
          );
        if (name === "text" && node.arguments.length >= 2)
          add(node, "button", "keyboard.text");
      }
      if (ts.isPropertyAssignment(node) && node.name.getText(ast) === "text")
        add(node.initializer, "projection", "text");
      if (
        ts.isShorthandPropertyAssignment(node) &&
        ts.isIdentifier(node.name) &&
        node.name.text === "text"
      )
        add(node.name, "projection", "text");
      // Freeze factories too: changing prose in a helper must invalidate its inventory even if the sink is unchanged.
      if (
        ts.isFunctionDeclaration(node) &&
        node.name &&
        /^(render|format|.*Keyboard$|.*Rows$|.*Label$)/.test(node.name.text) &&
        (file.includes("/telegram/") || file.includes("/shared/i18n/"))
      )
        add(node, "projection", `factory.${node.name.text}`);
    });
  }
  return result;
}

export function verifyInventory(
  sources: Record<string, string>,
  inventory: readonly OutboundSurface[],
  checkEvidence = false,
): string[] {
  const errors: string[] = [];
  const actual = discoverSurfaces(sources);
  const recorded = new Map(inventory.map((site) => [site.id, site]));
  if (recorded.size !== inventory.length) errors.push("duplicate-surface");
  for (const site of actual) {
    const record = recorded.get(site.id);
    if (!record) {
      errors.push(`uncovered-surface: ${site.id}`);
      continue;
    }
    recorded.delete(site.id);
    if (record.digest !== site.digest || record.expression !== site.expression)
      errors.push(`unmapped-expression: ${site.id}`);
    if (record.dependencies !== site.dependencies)
      errors.push(`unmapped-dependency: ${site.id}`);
    if (JSON.stringify(record.keys) !== JSON.stringify(site.keys))
      errors.push(`catalog-path-changed: ${site.id}`);
    for (const key of record.keys)
      if (!Object.hasOwn(catalogs.en, key) || !Object.hasOwn(catalogs.uk, key))
        errors.push(`missing-key: ${site.id}: ${key}`);
    if (checkEvidence) {
      if (record.residual)
        errors.push(`pending-branch-evidence: ${site.id}: ${record.residual}`);
      else if (
        !record.evidence ||
        !existsSync(record.evidence.file) ||
        !readFileSync(record.evidence.file, "utf8").includes(
          record.evidence.case,
        )
      )
        errors.push(`missing-bilingual-evidence: ${site.id}`);
      if (
        record.keys.length === 0 &&
        (!record.dynamic?.position || !record.dynamic.reason)
      )
        errors.push(`unjustified-dynamic-position: ${site.id}`);
    }
  }
  for (const id of recorded.keys()) errors.push(`stale-surface: ${id}`);
  return errors;
}

