      'async function renderStep(\n  deps: PlanningHandlerDependencies,\n  round: PlanningRound,\n  actions: readonly MintedPlanningAction[],\n  now: Date,\n  /**\n   * A pre-built availability projection, when the caller has already read one.\n   *\n   * `/plan_status` needs the projection\'s outcome BEFORE this function runs, to\n   * choose which of the round\'s two messages it is re-posting. Reading it twice\n   * — once for the slot and once here — would leave a window in which a\n   * concurrent answer commits between them, and the slot would then disagree\n   * with the message actually rendered: an announcement posted for a round that\n   * is collecting again, or `announcementMessageId` re-pointed at an\n   * availability card. Omitted, this reads its own, so every other caller is\n   * unchanged.\n   */\n  availability?: AvailabilityStepProjection,\n  /**\n   * Which of a non-draft round\'s two messages this render is producing, when\n   * the caller has already decided.\n   *\n   * Same register as the projection above: a caller that has consulted a durable\n   * claim this function cannot see — `claimAnnouncementRepost`, which decides\n   * whether the band may be NOTIFIED at all — says which card it is producing\n   * rather than letting the predicate below re-derive a decision the caller has\n   * deliberately superseded. Gating only the SLOT would leave this predicate in\n   * charge of the message body, so a refused claim would still post the\n   * ready-to-book copy with a live booking control (D-21a, gap G-01).\n   *\n   * Omitted, the predicate decides exactly as it does today, so `/plan`\'s\n   * resumed-round caller and every other existing caller are byte-identical.\n   */\n  card?: "availability" | "announcement",\n): Promise<RenderedStep> {\n  // STATUS before STEP, and the order is the guard — the same order\n  // `mintStepActions` uses to decide what to mint. `step` is only meaningful\n  // while the round is a draft: a promoted round keeps `REVIEW` in the column\n  // forever, so without this branch a `/plan_status` re-post of a collecting\n  // round would draw the wizard\'s review card over the availability card the\n  // band is answering on.\n  //\n  // Which controls the card ends up with is decided entirely by `actions`, which\n  // `status()` chose from the same position: a confirmed round carries its two\n  // loaded answer tokens, and a booked one carries none, so `controlTokens`\n  // answers `undefined` for every control and `planningControlRows` drops them.\n  if (round.status !== PlanningRoundStatus.DRAFT) {\n    const projection =\n      availability ?? (await deps.planning.availabilityProjection(round));\n    // An explicit request wins, because the caller that makes one knows\n    // something this function cannot read: whether the announcement window has\n    // been claimed (gap G-01). Absent one, chosen by STATE, never by a column\n    // alone (Open Question 2). A round that is confirmed, has announced, and is\n    // currently ready or blocked is showing the band an announcement. A\n    // collecting round instead gets the card. The fact is read off the\n    // projection\'s own outcome field, which `availabilityOutcome` already\n    // produced; it is never re-derived here.\n    if (card === "availability") {\n      return withoutEmptyKeyboard(\n        renderAvailabilityCard(\n          projection,\n          controlTokens(actions),\n          await resolvePresentationLocale(\n            deps.prisma,\n            round.chatId,\n            deps.logger,\n          ),\n          planningTimeRange(round),\n        ),\n      );\n    }\n    const body = announcementBody(round, projection);\n    if (body !== null) {\n      return withoutEmptyKeyboard(\n        body(\n          projection,\n          controlTokens(actions),\n          await resolvePresentationLocale(\n            deps.prisma,\n            round.chatId,\n            deps.logger,\n          ),\n          planningTimeRange(round),\n        ),\n      );\n    }\n    return withoutEmptyKeyboard(\n      renderAvailabilityCard(\n        projection,\n        controlTokens(actions),\n        await resolvePresentationLocale(deps.prisma, round.chatId, deps.logger),\n        planningTimeRange(round),\n      ),\n    );\n  }\n\n  if (round.step === PlanningStep.DAY) {\n    // The projection decides WHICH seven days and how each is marked; the\n    // minted actions decide only which opaque token sits behind each one.\n    const tokens = new Map<string, string>();\n    for (const action of actions) {\n      if (action.target.action !== "day") continue;\n      tokens.set(action.target.date, action.token);\n    }\n    const projection = await deps.planning.dayStepProjection(round, now);\n    return renderDayStep(\n      projection,\n      (isoDate) => tokens.get(isoDate),\n      // The day step mints no Back — it is the first step — but a round\n      // abandoned on it is still takeover-eligible, so the control lookup is\n      // passed through here too.\n      controlTokens(actions),\n      await resolvePresentationLocale(deps.prisma, round.chatId, deps.logger),\n    );\n  }\n\n  if (round.step === PlanningStep.TIME) {\n    // Same division of labour as the day card: the projection decides which\n    // hours and how each is marked, the minted actions only which opaque token\n    // sits behind each one.\n    const tokens = new Map<number, string>();\n    for (const action of actions) {\n      if (action.target.action !== "time") continue;\n      tokens.set(action.target.startMinute, action.token);\n    }\n    const projection = await deps.planning.timeStepProjection(round, now);\n    return renderTimeStep(\n      projection,\n      (startMinute) => tokens.get(startMinute),\n      controlTokens(actions),\n      await resolvePresentationLocale(deps.prisma, round.chatId, deps.logger),\n    );\n  }\n\n  // Review: the terminal card of the phase (D-04). The time buttons do not\n  // survive the step that owned them — leaving them live on an anchor whose\n  // round has already moved on would let a second tap fight the first (D-01 —\n  // one card, edited) — and Confirm and Back take their place.\n  const projection = await deps.planning.reviewStepProjection(round);\n  return renderReviewStep(\n    projection,\n    controlTokens(actions),\n    await resolvePresentationLocale(deps.prisma, round.chatId, deps.logger),\n    planningTimeRange(round),\n  );\n}',
